from lib import *
S = SS('p62')
steps = [
    step("单线程、每行一个事务(提交一次)插入 2000 行(每行约 2 KB),每种设置重复 5 次取中位数:journal_mode=delete + synchronous=FULL 中位 3476 次提交/秒(1462–3645);delete + NORMAL 3347(2453–4087);wal + FULL 21166(5058–21767);wal + NORMAL 36454(3172–46450);wal + OFF 64743(63177–65096)。波动很大(最小到最大差十几倍),只能看量级:WAL 比默认的 delete 日志快一个数量级左右,synchronous 从 FULL 降到 NORMAL 在 WAL 下还能再快一些。这是在这台 Mac 的本地磁盘上的结果,macOS 上 fsync 本身是否真正落盘我没有测。", t=tl(S(1)), done=lidx(S(1), 'journal_mode=wal    synchronous=NORMAL'), mark=lidx(S(1), 'journal_mode=delete synchronous=FULL'), b=bars([['delete + FULL', 3476, '3476'], ['delete + NORMAL', 3347, '3347'], ['wal + FULL', 21166, '21166'], ['wal + NORMAL', 36454, '36454'], ['wal + OFF', 64743, '64743']], 66000, mark=[0, 1], done=[3]), kv=KV([['delete 日志', '约 3400 次提交/秒'], ['wal + NORMAL', '约 36000 次提交/秒(波动大)'], ['说明', '单次测量波动 3–15 倍,只看量级']], ['wal + NORMAL'])),
    step("4 个线程各自一个连接,各写 500 行(每行一个事务,BEGIN IMMEDIATE),重复 5 次。delete 模式:busy 等待 timeout=0 时中位 3000 行/秒,遇到 “database is locked” 重试的次数中位 1505(1063–5613);timeout=0.05 秒:3535 行/秒,重试 13 次;timeout=5 秒:2804 行/秒,重试 0 次。wal 模式:timeout=0:8292 行/秒,重试 158 次(157–287);timeout=0.05:13324 行/秒,重试 1 次;timeout=5:9584 行/秒,重试 0 次。每次最终都是 2000 行。多个线程各开连接写同一个库,不设等待就会不停地遇到 locked,设了 busy 等待(Python 的 timeout 参数)才平稳;WAL 下的吞吐明显高。", t=tl(S(2)), done=lidx(S(2), 'journal_mode=wal    busy 等待 timeout=5'), mark=lidx(S(2), 'journal_mode=delete busy 等待 timeout=0:'), b=bars([['delete timeout=0 重试次数', 1505, '1505'], ['delete timeout=5 重试次数', 0, '0'], ['wal timeout=0 重试次数', 158, '158'], ['wal timeout=5 重试次数', 0, '0']], 1600, mark=[0, 2], done=[1, 3]), kv=KV([['delete, timeout=0', '重试 1505 次'], ['wal, timeout=0', '重试 158 次'], ['timeout=5(两种模式)', '0 次重试']], ['timeout=5(两种模式)'])),
    step("换成“一个写线程 + 队列”:4 个生产线程各往 queue.Queue 放 500 行,写线程收齐一批就一次提交(WAL 模式,重复 5 次):批大小 1 时中位 8310 行/秒(5360–11995),提交 2000 次;批大小 10:49717 行/秒(2952–52716),提交 200 次;批大小 100:90207 行/秒(78879–114349),提交 20 次;批大小 500:117097 行/秒(97004–122708),提交 4 次。全程没有 locked 错误(只有一个连接在写)。批大小 1 和上一节“4 个线程各自写”的 timeout=5 结果(9584)在同一量级,收益主要来自一次提交多行;批大小从 100 到 500 的差别不大(范围有重叠)。", t=tl(S(3)), done=lidx(S(3), '批大小 100'), mark=lidx(S(3), '批大小   1'), b=bars([['批大小 1', 8310, '8310'], ['批大小 10', 49717, '49717'], ['批大小 100', 90207, '90207'], ['批大小 500', 117097, '117097']], 120000, mark=[0], done=[2, 3]), kv=KV([['批大小 1', '8310 行/秒,提交 2000 次'], ['批大小 100', '90207 行/秒,提交 20 次'], ['locked 错误', '没有(只有一个写连接)']], ['批大小 100'])),
    step("写的时候读:写连接开事务插入若干行后停 0.5 秒再提交,读连接 timeout=0 去 SELECT count(*)。未提交的行很少(10 行)时,delete 和 wal 都读到 0 行;未提交的数据较多(1000 行,约 2.0 MiB)时:delete 模式读连接得到 “database is locked”,wal 模式读到 0 行(提交前的状态),都只用了零点几毫秒。写提交之后两种模式再读都是 1000 行。WAL 下读不被写挡住;delete 模式下写得多了读会被挡住(我没有去查是什么触发了这个差别,只是观察到 10 行与 1000 行不同)。", t=tl(S(4)), done=lidx(S(4), 'journal_mode=wal    未提交的写事务里有 1000 行'), mark=lidx(S(4), 'journal_mode=delete 未提交的写事务里有 1000 行'), b=bars([['delete,10 行:读到', 0, '0 行'], ['delete,1000 行', 1, 'locked 错误'], ['wal,1000 行:读到', 0, '0 行']], 1.3, mark=[1], done=[0, 2]), kv=KV([['delete, 10 行', '读到 0 行'], ['delete, 1000 行', 'database is locked'], ['wal, 1000 行', '读到 0 行,不被挡']], ['wal, 1000 行'])),
    step("WAL 文件会长到多大(单线程,每 100 行提交一次,共 20000 行,每行约 2 KB):默认自动 checkpoint(1000 页)时 -wal 过程中最大 4.1 MiB,写完时主库 38296 KiB、-wal 4217 KiB;关掉自动 checkpoint:-wal 最大 41.9 MiB,写完时主库只有 8 KiB、-wal 42910 KiB(数据都在 WAL 里);默认自动 checkpoint 但有一个读连接开着读事务一直不结束:-wal 也是 41.9 MiB(主库 8 KiB),此时手动 checkpoint(TRUNCATE) 返回 (1, 10665, 0),busy 为 1,没移回任何页;读事务结束后再 checkpoint,返回 (0, 0, 0),-wal 变成 0 KiB。长时间不结束的读事务会让 WAL 一直增长。", t=tl(S(5)), done=lidx(S(5), '一直开着读事务'), mark=lidx(S(5), '关掉自动 checkpoint'), b=bars([['默认:-wal 最大 MiB', 4.1, '4.1'], ['关自动 checkpoint:-wal 最大 MiB', 41.9, '41.9'], ['有长读事务:-wal 最大 MiB', 41.9, '41.9']], 45, done=[0], mark=[1, 2]), kv=KV([['默认', '-wal 最大 4.1 MiB'], ['关掉自动 checkpoint', '41.9 MiB'], ['有一直开着的读事务', '41.9 MiB,checkpoint 返回 busy=1']], ['有一直开着的读事务'])),
    step("Python sqlite3 的几个坑:默认 isolation_level='',连接刚建好 in_transaction=False,执行一条 INSERT 后 in_transaction=True(Python 隐式开了事务);此时另一个连接 SELECT count(*) 得到 0,commit 之后得到 1——忘了 commit,数据就一直对别的连接不可见。连接默认 check_same_thread=True,在另一个线程里用同一个连接,抛出 ProgrammingError(“SQLite objects created in a thread can only be used in that same thread”),所以多线程写用单独的写线程持有连接。", t=tl(S(6)), done=lidx(S(6), '另一个连接此时'), mark=lidx(S(6), '连接默认 check_same_thread=True'), b=bars([['INSERT 后另一个连接看到', 0, '0'], ['commit 后另一个连接看到', 1, '1']], 1.3, mark=[0], done=[1]), kv=KV([['隐式事务', 'INSERT 后 in_transaction=True'], ['不 commit', '别的连接看不到'], ['跨线程用连接', 'ProgrammingError']], ['不 commit'])),
]
A = mkartp('p62', 62, '爬虫,sqlite,WAL,单写线程,批量提交,checkpoint,Python,真实验证,动画演示',
    '在本机 sqlite 3.53.4 上实测:WAL 比默认日志模式每秒提交次数高一个数量级、多线程各开连接写同一个库的 locked 错误和 busy 等待、单写线程加队列的批大小对吞吐的影响、WAL 下读写互不挡、以及长读事务会让 WAL 一直增长。',
    '用 sqlite 保存抓取结果很方便,但多个爬虫线程同时写会撞上 locked。WAL 模式、busy 等待、单写线程加队列分别解决什么,代价是什么?这篇用 sqlite 3.53.4 一项项测。',
    [('3347 对 36454 次/秒', '单线程每行一个事务:默认日志模式(delete + NORMAL) 与 WAL + NORMAL 的中位数(波动很大,只看量级)'), ('1505 对 0 次', '4 个线程各自写、delete 模式下 busy 等待为 0 时 “database is locked” 的重试次数中位 与 等待 5 秒时的重试次数'), ('41.9 MiB 的 WAL', '有一个读事务一直不结束时,写 20000 行(每行约 2 KB)后 -wal 文件的大小(主库只有 8 KiB)')],
    [('WAL 与 synchronous', '<p>每行一个事务的写入主要花在每次提交的磁盘同步上。同样 2000 行,WAL 模式的提交速度比默认的 delete 日志高一个数量级左右;synchronous 降低还能更快,但 OFF 在掉电时可能损坏数据,NORMAL 在 WAL 下的风险要看文档(这里没有测掉电)。单次测量波动很大,表里给的是 5 次中位数与范围。</p>'),
     ('多线程各自写', '<p>多个线程各开连接写同一个库,sqlite 同一时刻只允许一个写者。连接的 busy 等待为 0 时,抢不到锁就立刻报 “database is locked”(delete 模式中位重试 1505 次);设了等待(Python 里是 connect 的 timeout 参数,默认 5 秒)就由 sqlite 在内部重试,实验里重试次数为 0。WAL 下吞吐更高。</p>'),
     ('单写线程加队列', '<p>爬虫线程把结果放进 queue.Queue,由一个写线程持有唯一的连接、攒一批再提交。实验里批大小 1 时 8310 行/秒,批大小 100 时 90207 行/秒;提交次数从 2000 降到 20。没有 locked 错误,因为只有一个写者。队列无上限时写线程跟不上会占用内存(队列满时让生产者等待,见第 22 篇)。</p>'),
     ('读不被写挡住', '<p>WAL 下读连接读到的是写事务提交前的状态,不会被正在进行的写事务挡住;delete 模式下实验里 1000 行(约 2 MiB)的未提交写事务让读连接报 locked,而 10 行的没有。我只是观察到这个差别,没有去查原因。</p>'),
     ('WAL 文件会长大', '<p>默认每累积 1000 页自动做 checkpoint,-wal 最大 4.1 MiB。关掉自动 checkpoint,或者有一个读事务一直不结束,checkpoint 就无法把数据移回主库,-wal 长到 41.9 MiB(主库只有 8 KiB),手动 checkpoint(TRUNCATE) 返回 busy=1。读事务结束后再 checkpoint,-wal 回到 0 KiB。长时间开着的读事务(比如迭代一个很大的结果集边遍历边处理)是个隐患。</p>'),
     ('Python 的隐式事务', '<p>Python sqlite3 默认在第一条 INSERT 时隐式开事务,忘了 commit 别的连接就看不到数据;连接默认不能跨线程使用。写线程模式天然符合这个限制:连接只在写线程里创建和使用。</p>')],
    steps,
    [ENV_P + '。sqlite 3.53.4(Python 自带的 sqlite3 模块),数据库文件放在本机磁盘的临时目录;每行约 2 KB 的 BLOB;第一到三节各重复 5 次,给出中位数和最小–最大(波动很大,例如 wal + NORMAL 是 3172–46450 次/秒);第四到六节各一次',
     '没有验证:掉电或崩溃后的数据完整性(synchronous 各级别的真实差别);macOS 上 PRAGMA fullfsync 的影响;更多线程、更大的行、多个数据库文件;写线程的队列有上限时的背压效果;WAL 模式在网络文件系统上的限制;读事务期间 checkpoint 的 PASSIVE/RESTART 等其它模式;busy_timeout 之外的重试策略;checkpoint 返回的三个数字的确切含义(只观察了值,(0, 0, 0) 我没有去解释)'],
    'sqlite 单写线程')
